style.css:
@-moz-document domain("spotify.com") {
/* Echte panterprint uit de thumbnail */
:root {
  --leopard: url("data:image/jpeg;base64,");
}

/* Panterprint op de volledige pagina */
[data-testid="main-view-container"],
[data-testid="sidebar"],
[data-testid="now-playing-bar"] {
  background-image: var(--leopard) !important;
  background-repeat: repeat !important;
  background-size: 180px 120px !important;
  background-color: #49301f !important;
}

/* Donkere transparante laag voor leesbaarheid */
[data-testid="main-view-container"] {
  background-blend-mode: normal !important;
}

/* Teksten */
h1, h2, h3, p, span {
  color: #f5ead8 !important;
}
}
